          "type": "INTEGER",
          "description": "Reference to the customer"
        },
        {
          "name": "website_access",
          "type": "VARCHAR",
          "description": "Type of access level on the main website"
        },
        {
          "name": "finance_website_access",
          "type": "VARCHAR",
          "description": "Type of access level on the finance website"
        },
        {
          "name": "account_status",
          "type": "VARCHAR",
          "description": "Current status of the account"
        },
        {
          "name": "last_access_date",
          "type": "DATE",
          "description": "Last date the account was accessed"
        },
        {
